<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{History,Eye,Download,X,RefreshCw}from'@lucide/vue';
const props=defineProps<{visitId:string;contextKey:string}>(),emit=defineEmits(['denied']);
const expanded=ref(false),items=ref<any[]>([]),next=ref<string|null>(null),total=ref(0),asOf=ref(''),limit=ref(25),loading=ref(false),error=ref(''),loaded=ref(false),preview=ref(''),previewItem=ref<any>(null),fileBusy=ref(false);
let generation=0,fileGeneration=0,controller:AbortController|null=null,fileController:AbortController|null=null;
const time=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未登记',short=(s:string)=>s.slice(0,8).toUpperCase();
function closePreview(){fileGeneration++;fileController?.abort();fileController=null;if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';previewItem.value=null;fileBusy.value=false;}
function clear(){generation++;controller?.abort();controller=null;items.value=[];next.value=null;total.value=0;asOf.value='';loading.value=false;loaded.value=false;error.value='';closePreview();}
function denied(status:number){if(status===401||status===403){clear();expanded.value=false;emit('denied',status);return true;}return false;}
watch(()=>[props.visitId,props.contextKey],()=>{clear();expanded.value=false;});
async function load(more=false){if(loading.value)return;if(!more)clear();const gen=++generation;controller=new AbortController();const own=controller,visitId=props.visitId;loading.value=true;error.value='';const timer=setTimeout(()=>own.abort(),15000),q=new URLSearchParams({limit:String(limit.value)});if(more&&next.value)q.set('cursor',next.value);
 try{const r=await fetch(`/api/v1/care/visits/${visitId}/image-history?${q}`,{credentials:'same-origin',signal:own.signal}),b=await r.json().catch(()=>({}));if(gen!==generation)return;if(!r.ok){if(denied(r.status))return;throw Error(b.message||'读取影像原版失败。');}items.value=more?[...items.value,...b.items]:b.items;next.value=b.nextCursor;total.value=b.total;asOf.value=b.asOf;loaded.value=true;
 }catch(e){if(gen===generation)error.value=e instanceof Error&&e.name!=='AbortError'?e.message:'读取超时，请重新读取原版。';}finally{clearTimeout(timer);if(gen===generation){loading.value=false;controller=null;}}}
async function file(r:any,download=false){closePreview();const gen=++fileGeneration,visitId=props.visitId;fileController=new AbortController();const own=fileController;fileBusy.value=true;error.value='';const timer=setTimeout(()=>own.abort(),15000);
 try{const response=await fetch(`/api/v1/care/visits/${visitId}/image-history/${r.revisionId}/content${download?'?download=1':''}`,{credentials:'same-origin',signal:own.signal});if(gen!==fileGeneration)return;if(!response.ok){const b=await response.json().catch(()=>({}));if(denied(response.status))return;throw Error(b.message||'本版文件读取失败。');}const bytes=await response.arrayBuffer();if(gen!==fileGeneration)return;const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(gen!==fileGeneration)return;if(bytes.byteLength!==r.size||hash!==r.digest||hash!==response.headers.get('X-Content-SHA256')||response.headers.get('Content-Type')?.split(';')[0]!==r.mediaType)throw Error('本版文件大小、格式或摘要不一致，未显示文件。');const blob=new Blob([bytes],{type:r.mediaType}),url=URL.createObjectURL(blob);
  if(download){const a=document.createElement('a');a.href=url;a.download=`ADC-影像-${short(r.imageId)}-v${r.version}${r.mediaType==='image/png'?'.png':'.jpg'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else{preview.value=url;previewItem.value=r;}
 }catch(e){if(gen===fileGeneration)error.value=e instanceof Error&&e.name!=='AbortError'?e.message:'文件读取超时，请重试。';}finally{clearTimeout(timer);if(gen===fileGeneration){fileBusy.value=false;fileController=null;}}}
function toggle(){expanded.value=!expanded.value;if(expanded.value)load();else clear();}
function change(){clear();if(expanded.value)load();}
onBeforeUnmount(clear);
</script>
<template><section class="b-card image-history">
 <header class="ih-heading"><div><h2><History :size="19"/>影像归档原版</h2><p>查看本次就诊历次归档说明与原文件。</p></div><button class="b-button outline small" :aria-expanded="expanded" @click="toggle">{{expanded?'收起归档原版':'查看归档原版'}}</button></header>
 <template v-if="expanded"><div class="ih-controls"><label>每页原版<select aria-label="每页影像原版" v-model="limit" @change="change"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><button class="b-button outline small" :disabled="loading" @click="load()"><RefreshCw :size="15"/>重新读取</button></div>
 <p class="b-help">原版按当时归属的就诊显示。更正后的当前归属与文件以当前目录为准；旧版不会替换为后来的文件。人员标识固定，辅助姓名来自当前员工目录。</p>
 <p v-if="loaded" class="ih-summary">已显示 {{items.length}} / {{total}} 版 · 读取时点 {{time(asOf)}}</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><p v-if="loading" role="status">正在读取影像原版…</p><p v-if="loaded&&!items.length" class="b-empty">本次就诊尚无已保存的影像归档原版。</p>
 <article v-for="r in items" :key="r.revisionId" class="ih-version"><header><strong>影像 {{short(r.imageId)}} · 第 {{r.version}} 版</strong><span class="b-pill">{{r.imageType==='scan'?'检查影像':'诊疗照片'}}</span></header><div class="ih-facts"><p>影像形成<strong>{{time(r.formedAt)}}</strong></p><p>归档登记<strong>{{time(r.savedAt)}}</strong></p><p>原归档人员<strong>{{r.archivedBy.name}}</strong><small>{{r.archivedBy.id}}</small></p><p>本版操作人<strong>{{r.editor.name}}</strong><small>{{r.editor.id}}</small></p></div><div class="ih-body">{{r.description||'本版未填附加说明'}}</div><p>更正原因：{{r.reason||'本版未登记更正原因'}}</p><p class="ih-meta">原文件 {{short(r.fileId)}} · {{Math.ceil(r.size/1024)}} KB · {{r.mediaType}}</p><details><summary>原版与文件依据</summary><p>原版 {{r.revisionId}}</p><p>登记操作 {{r.operationId}}</p><p>原文件 {{r.fileId}}</p><p>SHA-256 {{r.digest}}</p></details><div class="ih-actions"><button class="b-button outline small" :disabled="fileBusy" @click="file(r)"><Eye :size="14"/>预览本版原文件</button><button class="b-button outline small" :disabled="fileBusy" @click="file(r,true)"><Download :size="14"/>下载本版原文件</button></div></article>
 <button v-if="next" class="b-button outline" :disabled="loading" @click="load(true)">读取更早归档原版</button><p v-if="fileBusy" role="status">正在校验本版原文件…</p>
 </template><div v-if="preview&&previewItem" class="b-backdrop"><section class="b-dialog ih-dialog" role="dialog" aria-modal="true" aria-label="影像原文件预览"><button class="b-close" aria-label="关闭原文件预览" @click="closePreview"><X :size="20"/></button><h2>影像 {{short(previewItem.imageId)}} · 第 {{previewItem.version}} 版</h2><p>形成 {{time(previewItem.formedAt)}} · 归档 {{time(previewItem.savedAt)}}</p><img :src="preview" alt="所选归档版本的原文件"/><p class="b-help">本版原文件已核对大小与摘要。</p></section></div>
</section></template>
<style scoped>
.image-history{padding:24px;min-width:0;font-size:15px;line-height:1.7}.ih-heading,.ih-heading h2,.ih-version header,.ih-controls,.ih-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.ih-heading{justify-content:space-between}.ih-heading h2{font-size:18px;margin:0}.ih-heading p{margin:6px 0;color:#61756f}.ih-controls{align-items:end;margin:20px 0 12px}.ih-controls label{display:grid;gap:6px}.ih-controls select{padding:9px 12px;border:1px solid #cedbd5;border-radius:8px;background:white}.ih-summary,.ih-meta,.ih-version small{font-size:13px;color:#61756f}.ih-version{padding:20px;border:1px solid #dce7e1;border-radius:10px;margin:18px 0;overflow-wrap:anywhere}.ih-version header strong{color:#176b52}.ih-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.ih-facts p{margin:12px 0}.ih-facts strong,.ih-facts small{display:block}.ih-body{padding:12px;background:#f5f8f6;border-radius:8px;white-space:pre-wrap}.ih-version details{font-size:13px;margin:12px 0}.ih-version summary{cursor:pointer;color:#176b52}.ih-version details p{margin:6px 0}.ih-dialog{width:min(900px,calc(100vw - 32px));max-height:90vh;overflow:auto}.ih-dialog img{display:block;max-width:100%;max-height:65vh;object-fit:contain;margin:16px auto}.image-history .b-help{font-size:14px;line-height:1.7}@media(max-width:760px){.image-history{padding:16px}.ih-version{padding:14px}.ih-facts{grid-template-columns:minmax(0,1fr)}.ih-heading{align-items:flex-start}}
</style>
